-- Reaction image URL migration: rewrites dbo.MessageReaction.ImageUrl from the legacy
-- twemoji-CDN / relative-custom-path URLs to the new self-hosted /reactions/{file} scheme.
-- Generated from C:\tmp\MessageReactions.xlsx (live DB export) - 562 distinct URLs, 0 gaps
-- (every historical reaction, including the England/Scotland/Wales subdivision flags, is
-- covered by the vendored jdecked/twemoji set - see WebApi/Assets/Reactions/NOTICE.md).
--
-- INTENDED WORKFLOW (do not just execute the whole file top to bottom):
--   1. Run everything up to and including the two SELECTs below.
--   2. Check RowsUpdated looks right (should be 9700ish) and the second SELECT (anything
--      NOT starting with /reactions/) is empty - a non-empty result means a live reaction
--      exists that wasn't in the xlsx export this script was generated from, and needs
--      investigating before committing.
--   3. Only then, separately, run either COMMIT TRANSACTION or ROLLBACK TRANSACTION at the
--      bottom of this file.
SET NOCOUNT ON;

DECLARE @Mapping TABLE (OldUrl NVARCHAR(500) NOT NULL PRIMARY KEY, NewUrl NVARCHAR(500) NOT NULL);


BEGIN TRANSACTION;

UPDATE r
SET r.ImageUrl = m.NewUrl
FROM dbo.MessageReaction r
JOIN @Mapping m ON r.ImageUrl = m.OldUrl;

SELECT @@ROWCOUNT AS RowsUpdated;

-- Should return zero rows. Anything here means a reaction URL exists in the live DB that
-- wasn't covered by the mapping above (e.g. added after the xlsx export was taken).
SELECT ImageUrl, COUNT(*) AS UsageCount
FROM dbo.MessageReaction
WHERE ImageUrl NOT LIKE '/reactions/%'
GROUP BY ImageUrl
ORDER BY UsageCount DESC;

